using System;
using System.Data;
using System.Web.UI;
using System.Data.SqlClient;
using System.Configuration;
using System.Collections.Generic;
using System.Linq;

namespace KienNguyen
{
    public partial class ProductDetails : Page
    {
        string connectionString = ConfigurationManager.ConnectionStrings["DefaultConnection"].ConnectionString;

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                LoadProductDetail();
            }
        }

        private void LoadProductDetail()
        {
            try
            {
                if (Request.QueryString["id"] != null)
                {
                    int productId;
                    if (int.TryParse(Request.QueryString["id"], out productId))
                    {
                        DataTable dt = GetProductByID(productId);

                        if (dt != null && dt.Rows.Count > 0)
                        {
                            // Hiển thị thông tin
                            DataRow row = dt.Rows[0];

                            lblProductName.Text = row["ProductName"].ToString();
                            lblPrice.Text = Convert.ToDecimal(row["Price"]).ToString("N0") + " đ";
                            lblDescription.Text = row["Description"].ToString().Replace("\n", "<br/>");

                            string imgUrl = row["ImageURL"].ToString();
                            if (!string.IsNullOrEmpty(imgUrl))
                            {
                                imgProduct.ImageUrl = "img/" + imgUrl;
                            }
                            else
                            {
                                imgProduct.ImageUrl = "https://via.placeholder.com/400x400?text=No+Image";
                            }

                            // Cập nhật tiêu đề trang
                            Page.Title = row["ProductName"].ToString();

                            divProductDetail.Visible = true;
                            divError.Visible = false;
                        }
                        else
                        {
                            // Không tìm thấy sản phẩm
                            divProductDetail.Visible = false;
                            divError.Visible = true;
                        }
                    }
                    else
                    {
                        // ID không hợp lệ
                        divProductDetail.Visible = false;
                        divError.Visible = true;
                    }
                }
                else
                {
                    // Không có ID
                    Response.Redirect("Default.aspx");
                }
            }
            catch (Exception ex)
            {
                // Xử lý lỗi (ví dụ chưa có DB)
                divProductDetail.Visible = false;
                divError.Visible = true;
                divError.InnerHtml += "<br/>Lỗi: " + ex.Message;
            }
        }

        private DataTable GetProductByID(int productId)
        {
            DataTable dt = new DataTable();
            using (SqlConnection con = new SqlConnection(connectionString))
            {
                string query = "SELECT * FROM Products WHERE ProductID = @ProductID";
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@ProductID", productId);
                    con.Open();
                    using (SqlDataAdapter sda = new SqlDataAdapter(cmd)) { sda.Fill(dt); }
                }
            }
            return dt;
        }

        protected void btnAddToCart_Click(object sender, EventArgs e)
        {
            AddToCart(false);
        }

        protected void btnBuyNow_Click(object sender, EventArgs e)
        {
            AddToCart(true);
        }

        private void AddToCart(bool isBuyNow)
        {
            if (Request.QueryString["id"] != null)
            {
                int productId;
                if (int.TryParse(Request.QueryString["id"], out productId))
                {
                    DataTable dt = GetProductByID(productId);
                    if (dt != null && dt.Rows.Count > 0)
                    {
                        DataRow row = dt.Rows[0];
                        KienNguyen.Models.CartItem item = new KienNguyen.Models.CartItem
                        {
                            ProductID = Convert.ToInt32(row["ProductID"]),
                            ProductName = row["ProductName"].ToString(),
                            Price = Convert.ToDecimal(row["Price"]),
                            ImageURL = row["ImageURL"].ToString(),
                            Quantity = 1
                        };

                        List<KienNguyen.Models.CartItem> cart = Session["Cart"] as List<KienNguyen.Models.CartItem>;
                        if (cart == null)
                        {
                            cart = new List<KienNguyen.Models.CartItem>();
                        }

                        var existingItem = cart.FirstOrDefault(i => i.ProductID == item.ProductID);
                        if (existingItem != null)
                        {
                            existingItem.Quantity++;
                        }
                        else
                        {
                            cart.Add(item);
                        }

                        Session["Cart"] = cart;

                        if (isBuyNow)
                        {
                            Response.Redirect("Cart.aspx");
                        }
                        else
                        {
                            ScriptManager.RegisterStartupScript(this, GetType(), "alert", "alert('Đã thêm vào giỏ hàng!');", true);
                        }
                    }
                }
            }
        }
    }
}

