        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                BindCart();
            }
        }

        private void BindCart()
        {
            List<CartItem> cart = Session["Cart"] as List<CartItem>;

            if (cart == null || cart.Count == 0)
            {
                lblEmpty.Visible = true;
                gvCart.Visible = false;
                divCartSummary.Visible = false;
            }
            else
            {
                lblEmpty.Visible = false;
                gvCart.Visible = true;
                divCartSummary.Visible = true;

                gvCart.DataSource = cart;
                gvCart.DataBind();

                decimal total = cart.Sum(item => item.TotalPrice);
                lblTotal.Text = total.ToString("N0") + " đ";
            }
        }

        protected void gvCart_RowCommand(object sender, GridViewCommandEventArgs e)
        {
            if (e.CommandName == "Remove")
            {
                int productId = Convert.ToInt32(e.CommandArgument);
                List<CartItem> cart = Session["Cart"] as List<CartItem>;

                if (cart != null)
                {
                    CartItem itemToRemove = cart.FirstOrDefault(i => i.ProductID == productId);
                    if (itemToRemove != null)
                    {
                        cart.Remove(itemToRemove);
                        Session["Cart"] = cart;
                    }
                }

                BindCart();
                // Update Master page cart count if possible, though a full reload is easiest
                Response.Redirect("Cart.aspx");
