```csharp
private void LoadProducts()
{
    int currentPage = 1;
    if (Request.QueryString["page"] != null)
    {
        int.TryParse(Request.QueryString["page"], out currentPage);
    }

    int? categoryId = null;
    if (Request.QueryString["cat"] != null)
    {
        int catId;
        if (int.TryParse(Request.QueryString["cat"], out catId))
        {
            categoryId = catId;
        }
    }

    string search = Request.QueryString["search"];
    int totalCount = 0;

    DataTable dtProducts = GetProductsPaged(currentPage, pageSize, categoryId, search, out totalCount);
    rptProducts.DataSource = dtProducts;
    rptProducts.DataBind();
    GeneratePager(totalCount, pageSize, currentPage, categoryId, search);
}
```

Phân trang sản phẩm:

```csharp
private DataTable GetProductsPaged(int pageIndex, int pageSize, int? categoryId,
    string searchKeyword, out int totalCount)
{
    string whereClause = " WHERE 1=1 ";
    if (categoryId.HasValue) whereClause += " AND CategoryID = @CategoryID ";
    if (!string.IsNullOrEmpty(searchKeyword)) whereClause += " AND ProductName LIKE @Search ";

    string countQuery = "SELECT COUNT(*) FROM Products " + whereClause;
    string dataQuery = "SELECT * FROM Products " + whereClause +
        " ORDER BY ProductID DESC " +
        " OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY";
}
